/// <summary>
/// Ejects a <see cref="ResourceNode"/>'s drops when it's depleted, rolling each <see cref="DropEntry"/>
/// in the node's config and spawning the results through <see cref="WorldItemSpawner"/> with a small
/// upward pop so they scatter and settle before flying to the player. Replaces the old inline
/// SpawnDrops on ResourceNode (single responsibility).
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceDropSpawner : MonoBehaviour
{
    [Tooltip("Upward impulse applied to each spawned drop so it pops out of the node.")]
    [SerializeField] private float _popImpulse = 1.1f;
    [Tooltip("Height above the node base that drops spawn from.")]
    [SerializeField] private float _spawnHeight = 0.25f;

    private ResourceNode _node;

    private void Awake() => _node = GetComponent<ResourceNode>();

    private void OnEnable()  { _node.OnDepleted += SpawnDrops; }
    private void OnDisable() { if (_node != null) _node.OnDepleted -= SpawnDrops; }

    private void SpawnDrops()
    {
        _node.OnDepleted -= SpawnDrops;

        ResourceNodeConfig cfg = _node.Config;
        if (cfg == null || cfg.drops == null) return;

        foreach (DropEntry drop in cfg.drops)
        {
            if (drop.item == null) continue;
            if (Random.value > drop.dropChance) continue;

            int count = Random.Range(drop.minCount, Mathf.Max(drop.minCount, drop.maxCount) + 1);
            for (int i = 0; i < count; i++)
            {
                Vector2 scatter = Random.insideUnitCircle * cfg.dropScatterRadius;
                Vector3 pos = transform.position + new Vector3(scatter.x, _spawnHeight, scatter.y);
                WorldItemSpawner.Spawn(drop.item, 1, pos, _popImpulse);
            }
        }
    }
}

using UnityEngine;
using UnityEngine.U2D;

/// <summary>
/// Apply the Custom/WaterFill material to the SpriteShapeRenderer on this GameObject.
/// All animation (scroll + wave) runs entirely in the shader via _Time — no per-frame
/// C# work required.  Expose this component to tweak scroll/wave values in the Inspector
/// at edit-time via MaterialPropertyBlock if needed, or just set them on the material asset.
/// </summary>
[RequireComponent(typeof(SpriteShapeRenderer))]
public class WaterAnimator : MonoBehaviour
{
    [Header("Shader Properties (mirrors Custom/WaterFill)")]
    [SerializeField] private float _scrollX       = 0.05f;
    [SerializeField] private float _scrollY       = 0.02f;
    [SerializeField] private float _waveAmplitude = 0.03f;
    [SerializeField] private float _waveFrequency = 1.5f;

    private static readonly int ScrollXId       = Shader.PropertyToID("_ScrollX");
    private static readonly int ScrollYId       = Shader.PropertyToID("_ScrollY");
    private static readonly int WaveAmplitudeId = Shader.PropertyToID("_WaveAmplitude");
    private static readonly int WaveFrequencyId = Shader.PropertyToID("_WaveFrequency");

    private SpriteShapeRenderer _renderer;
    private MaterialPropertyBlock _mpb;

    private void Awake()
    {
        _renderer = GetComponent<SpriteShapeRenderer>();
        _mpb = new MaterialPropertyBlock();
        ApplyProperties();
    }

#if UNITY_EDITOR
    private void OnValidate() => ApplyProperties();
#endif

    private void ApplyProperties()
    {
        if (_renderer == null) _renderer = GetComponent<SpriteShapeRenderer>();
        if (_mpb == null) _mpb = new MaterialPropertyBlock();

        _renderer.GetPropertyBlock(_mpb);
        _mpb.SetFloat(ScrollXId,       _scrollX);
        _mpb.SetFloat(ScrollYId,       _scrollY);
        _mpb.SetFloat(WaveAmplitudeId, _waveAmplitude);
        _mpb.SetFloat(WaveFrequencyId, _waveFrequency);
        _renderer.SetPropertyBlock(_mpb);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central UI relay — same factory/hub pattern as ResourceManager and PlayerInventory: gameplay
/// systems fire an inbound signal (<see cref="SignalShow"/> / <see cref="SignalHide"/> /
/// <see cref="SignalToggle"/>), the manager routes it to the matching reusable panel, then
/// broadcasts an outbound event (<see cref="OnPanelShown"/> / <see cref="OnPanelHidden"/>).
///
/// Callers never reference a concrete screen — they only know a <see cref="UIPanelId"/> and reach
/// the manager through <see cref="Instance"/>. The manager owns the list of reusable panels and
/// reuses them (show/hide), never instantiating per request.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> and the registry
/// exist before any caller's Awake/OnEnable.
/// </summary>
[DefaultExecutionOrder(-100)]
public class UIManager : MonoBehaviour
{
    public static UIManager Instance { get; private set; }

    [Tooltip("Log each show/hide signal. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    [Tooltip("Reusable panels managed here. Drop UIPanel components in, or Register at runtime.")]
    [SerializeField] private List<UIPanel> _panels = new();

    private readonly Dictionary<UIPanelId, IUIPanel> _registry = new();

    /// <summary>Raised after a panel is shown. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelShown;
    /// <summary>Raised after a panel is hidden. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelHidden;

    // ── Signals (inbound) ───────────────────────────────────────────────────────

    /// <summary>Signal: show the panel with this id. No-op (warns) if none is registered.</summary>
    public void SignalShow(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] show {id}");
        panel.Show();
        OnPanelShown?.Invoke(id);
    }

    /// <summary>Signal: hide the panel with this id.</summary>
    public void SignalHide(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] hide {id}");
        panel.Hide();
        OnPanelHidden?.Invoke(id);
    }

    /// <summary>Signal: toggle the panel's visibility.</summary>
    public void SignalToggle(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (panel.IsVisible) SignalHide(id);
        else SignalShow(id);
    }

    public bool IsVisible(UIPanelId id) => TryGet(id, out IUIPanel p, warn: false) && p.IsVisible;

    // ── Registration ──────────────────────────────────────────────────────────

    /// <summary>Register a panel at runtime (panels in the serialized list register automatically).</summary>
    public void Register(IUIPanel panel)
    {
        if (panel == null || panel.PanelId == UIPanelId.None) return;
        _registry[panel.PanelId] = panel;
    }

    public void Unregister(IUIPanel panel)
    {
        if (panel == null) return;
        if (_registry.TryGetValue(panel.PanelId, out IUIPanel existing) && existing == panel)
            _registry.Remove(panel.PanelId);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[UIManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;

        foreach (UIPanel panel in _panels)
        {
            if (panel == null) continue;
            if (panel.PanelId == UIPanelId.None)
            {
                Debug.LogWarning($"[UIManager] '{panel.name}' has PanelId.None; skipped.", panel);
                continue;
            }
            Register(panel);
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private bool TryGet(UIPanelId id, out IUIPanel panel, bool warn = true)
    {
        if (_registry.TryGetValue(id, out panel) && panel != null) return true;
        if (warn) Debug.LogWarning($"[UIManager] No panel registered for {id}.", this);
        return false;
    }
}

