/// <summary>
/// The physical material of a meleeable surface, used to decide which tool the
/// wrench multitool "transforms" into when swung at it (and so which attack
/// animation plays). Air (nothing hovered) is handled by the swing controller,
/// not represented here.
/// </summary>
public enum SurfaceMaterial
{
    Wood,
    Metal,
    Rock,
}

/// <summary>
/// Marks any object as a meleeable surface with a <see cref="SurfaceMaterial"/>.
/// Drop on crates, walls, etc. so the wrench reads them as wood/metal/rock and
/// swings the matching tool. <see cref="ResourceNode"/> does NOT need this — it
/// derives its own tool from its required-tool config; this is for non-resource
/// props that still want the tool-swap read.
///
/// AttackAnimIndex maps SurfaceMaterial → Animator AttackIndex (1-4), matching
/// <see cref="ResourceNode.AttackAnimIndex"/>: Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4.
/// </summary>
public class HittableSurface : MonoBehaviour
{
    [Tooltip("Physical material of this surface. Decides which tool the wrench swings: Wood→Axe, Metal→Hammer, Rock→Pick.")]
    [SerializeField] private SurfaceMaterial _material = SurfaceMaterial.Wood;

    public SurfaceMaterial Material => _material;

    /// <summary>Animator AttackIndex for this surface's matching tool.</summary>
    public int AttackAnimIndex => _material switch
    {
        SurfaceMaterial.Wood  => 2, // axe
        SurfaceMaterial.Metal => 3, // hammer
        SurfaceMaterial.Rock  => 1, // pick
        _                     => 4, // wrench (shouldn't hit; defensive)
    };
}

using UnityEngine;

/// <summary>
/// Stub robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and ticks it down over
/// time; exposes charge/drain API. The HUD reads the battery purely through
/// <see cref="IntVariable.OnChanged"/> — same hub pattern as the other managers (this writes the
/// value, listeners react). Replace the passive-drain placeholder with real costs (actions, tools,
/// time-of-day) when the energy economy is designed.
///
/// One per scene; lives on a manager GameObject (e.g. MANAGERS/BATTERY).
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. 0 = no auto-drain (placeholder economy).")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        _battery.Value = Mathf.Clamp(value, Min, Max);
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _drainPerSecond <= 0f || _battery == null || IsEmpty) return;

        _accum += _drainPerSecond * Time.deltaTime;
        if (_accum < 1f) return;

        int whole = Mathf.FloorToInt(_accum);
        _accum -= whole;
        Drain(whole);
    }
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// Shows the active inventory item as a held prop in the cube character's hand socket.
/// Listens to <see cref="PlayerInventory"/> slot changes and swaps the visual: the
/// item's <see cref="ItemDefinition.worldPrefab"/> is instantiated (stripped of its
/// world-pickup behaviour and physics so it's purely cosmetic), or a small placeholder
/// cube if the item has no prefab. Empty / no active item → empty hand.
///
/// Player-side visual (parents the prop under the hand <see cref="_socket"/>), so it stays on the
/// Player GameObject. It no longer requires <see cref="PlayerInventory"/> on the same object — the
/// inventory is now a standalone manager, reached via <see cref="PlayerInventory.Instance"/>.
/// </summary>
public class HeldItemSocket : MonoBehaviour
{
    [SerializeField] private PlayerInventory _inventory;
    [Tooltip("Hand transform the held prop is parented under (e.g. ProceduralCharacterDriver's HandSocketR).")]
    [SerializeField] private Transform _socket;
    [Tooltip("Uniform scale applied to the held prop in the hand.")]
    [SerializeField] private float _heldScale = 0.5f;
    [Tooltip("Placeholder cube colour used when an item has no worldPrefab.")]
    [SerializeField] private Color _placeholderColor = new Color(0.8f, 0.7f, 0.2f, 1f);

    private GameObject _current;
    private ItemDefinition _shownItem;

    private void Awake()
    {
        if (_inventory == null) _inventory = PlayerInventory.Instance;
    }

    private void OnEnable()
    {
        if (_inventory != null)
        {
            _inventory.OnActiveSlotChanged += OnActiveSlotChanged;
            _inventory.OnSlotChanged += OnSlotChanged;
        }
        Refresh();
    }

    private void OnDisable()
    {
        if (_inventory != null)
        {
            _inventory.OnActiveSlotChanged -= OnActiveSlotChanged;
            _inventory.OnSlotChanged -= OnSlotChanged;
        }
    }

    private void OnActiveSlotChanged(int _) => Refresh();

    private void OnSlotChanged(int slot)
    {
        // Only the active slot affects what's in the hand.
        if (_inventory != null && slot == _inventory.ActiveSlotIndex) Refresh();
    }

    private void Refresh()
    {
        if (_socket == null) return;
        ItemDefinition item = _inventory != null ? _inventory.ActiveItem : null;
        if (item == _shownItem) return; // already showing the right thing

        Clear();
        _shownItem = item;
        if (item == null) return;

        _current = item.worldPrefab != null ? BuildFromPrefab(item) : BuildPlaceholder();
        _current.transform.SetParent(_socket, false);
        _current.transform.localPosition = Vector3.zero;
        _current.transform.localRotation = Quaternion.identity;
        _current.transform.localScale = Vector3.one * _heldScale;
    }

    private GameObject BuildFromPrefab(ItemDefinition item)
    {
        GameObject go = Instantiate(item.worldPrefab);
        go.name = $"Held_{item.itemId}";
        StripToVisual(go);
        return go;
    }

    private GameObject BuildPlaceholder()
    {
        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Cube);
        go.name = "Held_Placeholder";
        var col = go.GetComponent<Collider>();
        if (col != null) Destroy(col);
        var r = go.GetComponent<Renderer>();
        if (r != null) r.material.color = _placeholderColor;
        return go;
    }

    /// <summary>Strip pickup/physics behaviour so the held copy is cosmetic only.
    /// Order matters: WorldItem has [RequireComponent(typeof(Collider))], so the WorldItem
    /// (and any other behaviour depending on the collider/body) must be destroyed BEFORE the
    /// collider, or Unity refuses the removal and logs a dependency error.</summary>
    private static void StripToVisual(GameObject go)
    {
        foreach (var wi in go.GetComponentsInChildren<WorldItem>()) Destroy(wi);
        foreach (var mb in go.GetComponentsInChildren<DroppedItemMagnet>()) Destroy(mb);
        foreach (var rb in go.GetComponentsInChildren<Rigidbody>()) Destroy(rb);
        foreach (var col in go.GetComponentsInChildren<Collider>()) Destroy(col);
    }

    private void Clear()
    {
        if (_current != null) Destroy(_current);
        _current = null;
        _shownItem = null;
    }
}

using UnityEngine;

/// <summary>
/// A world-anchored interaction prompt: which key, what action, an optional target name, and the
/// transform to float the prompt over. Rendered generically by the HUD — neither the HUD nor the
/// aimer know concrete interactable types. Anything interactable provides one of these by
/// implementing <see cref="IInteractionPromptProvider"/> (E Pick Up, E Inspect, E Talk, Q Grapple…).
/// </summary>
public readonly struct InteractionPrompt
{
    public readonly string Key;     // "E", "Q", …
    public readonly string Verb;    // "Pick Up", "Inspect", "Talk", "Grapple"
    public readonly string Label;   // optional target name (e.g. item / NPC name)
    public readonly Transform Anchor;

    public InteractionPrompt(string key, string verb, Transform anchor, string label = null)
    {
        Key = key;
        Verb = verb;
        Anchor = anchor;
        Label = label;
    }

    public bool IsValid => Anchor != null && !string.IsNullOrEmpty(Verb);

    /// <summary>Display text, e.g. "[E]  Pick Up Wrench" or "[Q]  Grapple".</summary>
    public string Display =>
        string.IsNullOrEmpty(Label) ? $"[{Key}]  {Verb}" : $"[{Key}]  {Verb} {Label}";
}

/// <summary>
/// Implemented by any world object the player can target for a prompted interaction. The aimer
/// surfaces the hovered provider; the HUD renders its prompt. Add new interactables by implementing
/// this — no changes to the aimer or HUD required.
/// </summary>
public interface IInteractionPromptProvider
{
    /// <summary>Return true and a valid prompt when an interaction is currently offered.</summary>
    bool TryGetPrompt(out InteractionPrompt prompt);
}

