using UnityEngine;

/// <summary>
/// Shared runtime integer backed by a ScriptableObject (Architect variable pattern).
/// The serialized value is only the starting amount; the live value is non-serialized
/// and resets on every play session / domain reload so the asset never bleeds state
/// between runs. Listen to <see cref="OnChanged"/> to drive UI.
///
/// Used for out-of-inventory currencies such as Echo Shards.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Variables/Int Variable", fileName = "IntVariable")]
public class IntVariable : ScriptableObject
{
    [Tooltip("Value the runtime amount is reset to when play begins.")]
    [SerializeField] private int _initialValue;

    [NonSerialized] private int _value;
    [NonSerialized] private bool _initialised;

    /// <summary>Raised whenever the value changes. Argument is the new value.</summary>
    public event Action<int> OnChanged;

    public int Value
    {
        get { EnsureInit(); return _value; }
        set
        {
            EnsureInit();
            if (_value == value) return;
            _value = value;
            OnChanged?.Invoke(_value);
        }
    }

    /// <summary>Add (or subtract) an amount and notify listeners.</summary>
    public void Add(int amount) => Value += amount;

    private void EnsureInit()
    {
        if (_initialised) return;
        _value = _initialValue;
        _initialised = true;
    }

    // Force a re-init on the next access after entering play / reloading the domain.
    private void OnEnable() => _initialised = false;
}

using UnityEngine;

/// <summary>
/// Runtime handle to the player's Transform. <see cref="PlayerAnchorRegistrar"/> on the
/// player sets this on enable. Lets runtime-spawned objects (dropped items flying to the
/// player) locate the player through an Inspector-assigned SO reference instead of
/// <c>FindObjectOfType</c>/<c>GameObject.Find</c> (both banned by the Flynn Architect rules).
///
/// Never serialise a scene reference into this asset — <see cref="Current"/> is non-serialized
/// and only ever set at runtime.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Player Anchor", fileName = "PlayerAnchor")]
public class PlayerAnchor : ScriptableObject
{
    /// <summary>The live player Transform, or null when no player is registered.</summary>
    public Transform Current { get; private set; }

    public bool HasPlayer => Current != null;

    public void Set(Transform t) => Current = t;

    /// <summary>Clear only if <paramref name="t"/> is the currently registered transform.</summary>
    public void Clear(Transform t) { if (Current == t) Current = null; }
}

using System;
using UnityEngine;

/// <summary>
/// SO event channel raised on every successful resource hit. Carries the struck
/// <see cref="ResourceNode"/> and its remaining health fraction (0-1) so listeners
/// (the HUD world-anchored HP bar) can position and fill a bar without holding a direct
/// reference to the node. Decouples resources from UI per the Architect rules.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Resource/Hit Channel", fileName = "ResourceHitChannel")]
public class ResourceHitChannel : ScriptableObject
{
    /// <summary>(node, health01) — health01 is CurrentHealth / maxHealth after the hit.</summary>
    public event Action<ResourceNode, float> OnHit;

    public void Raise(ResourceNode node, float health01)
    {
        if (node == null) return;
        OnHit?.Invoke(node, Mathf.Clamp01(health01));
    }
}

