/// <summary>
/// Drives the <see cref="InteractTagPanel"/> from the hover source. Reads
/// <see cref="PlayerMouseAimer.HoveredInteractable"/> each frame and positions the
/// panel at the interactable's world anchor with its prompt text. When nothing is
/// hovered the tag is hidden.
///
/// The tag is a pre-existing UIDocument under the UI manager, customisable via UXML/USS.
/// This presenter only shows/hides it and updates the anchor position and text.
/// </summary>
public class WorldInteractTagPresenter : MonoBehaviour
{
    [SerializeField] private PlayerMouseAimer _aimer;
    [SerializeField] private InteractTagPanel _tagPanel;

    private void Awake()
    {
        if (_aimer == null) _aimer = FindObjectOfType<PlayerMouseAimer>();
        if (_tagPanel == null) _tagPanel = FindObjectOfType<InteractTagPanel>();
    }

    private void LateUpdate()
    {
        if (_aimer == null || _tagPanel == null) return;

        IInteractionPromptProvider hovered = _aimer.HoveredInteractable;

        // Interface refs to destroyed Unity objects bypass the fake-null check.
        if (hovered is UnityEngine.Object obj && obj == null) hovered = null;

        if (hovered != null && hovered.TryGetPrompt(out InteractionPrompt prompt) && prompt.IsValid)
        {
            _tagPanel.Show(prompt.Display);
        }
        else
        {
            _tagPanel.HideTag();
        }
    }
}

using UnityEngine;

/// <summary>
/// Ejects a <see cref="ResourceNode"/>'s drops when it's depleted, rolling each <see cref="DropEntry"/>
/// in the node's config and spawning the results through <see cref="WorldItemSpawner"/> with a small
/// upward pop so they scatter and settle before flying to the player. Replaces the old inline
/// SpawnDrops on ResourceNode (single responsibility).
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceDropSpawner : MonoBehaviour
{
    [Tooltip("Upward impulse applied to each spawned drop so it pops out of the node.")]
    [SerializeField] private float _popImpulse = 1.1f;
    [Tooltip("Height above the node base that drops spawn from.")]
    [SerializeField] private float _spawnHeight = 0.25f;

    private ResourceNode _node;

    private void Awake() => _node = GetComponent<ResourceNode>();

    private void OnEnable()  { _node.OnDepleted += SpawnDrops; }
    private void OnDisable() { if (_node != null) _node.OnDepleted -= SpawnDrops; }

    private void SpawnDrops()
    {
        _node.OnDepleted -= SpawnDrops;

        ResourceNodeConfig cfg = _node.Config;
        if (cfg == null || cfg.drops == null) return;

        foreach (DropEntry drop in cfg.drops)
        {
            if (drop.item == null) continue;
            if (Random.value > drop.dropChance) continue;

            int count = Random.Range(drop.minCount, Mathf.Max(drop.minCount, drop.maxCount) + 1);
            for (int i = 0; i < count; i++)
            {
                Vector2 scatter = Random.insideUnitCircle * cfg.dropScatterRadius;
                Vector3 pos = transform.position + new Vector3(scatter.x, _spawnHeight, scatter.y);
                WorldItemSpawner.Spawn(drop.item, 1, pos, _popImpulse);
            }
        }
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// Plays the break animation when a <see cref="ResourceNode"/> is depleted: disables its colliders,
/// disables the <see cref="Billboard"/> on the visual (so our topple rotation sticks), then topples
/// the sprite while fading its alpha to zero, and finally destroys the GameObject. Owns the node's
/// removal — its presence is what tells <see cref="ResourceNode"/> not to self-destroy on depletion.
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceDeathFall : MonoBehaviour
{
    [Tooltip("Visual to topple/fade. Defaults to this transform.")]
    [SerializeField] private Transform _visualRoot;
    [Tooltip("Sprite faded to transparent during the fall. Auto-found in children if empty.")]
    [SerializeField] private SpriteRenderer _spriteRenderer;
    [SerializeField] private float _fallDuration = 0.7f;
    [SerializeField] private float _fadeDuration = 0.55f;
    [Tooltip("Degrees the sprite topples as it falls.")]
    [SerializeField] private float _toppleAngle = 82f;
    [Tooltip("World units the sprite sinks as it falls.")]
    [SerializeField] private float _sink = 0.35f;

    private ResourceNode _node;

    private void Awake()
    {
        _node = GetComponent<ResourceNode>();
        if (_visualRoot == null) _visualRoot = transform;
        if (_spriteRenderer == null) _spriteRenderer = GetComponentInChildren<SpriteRenderer>();
    }

    private void OnEnable()  { _node.OnDepleted += HandleDepleted; }
    private void OnDisable() { if (_node != null) _node.OnDepleted -= HandleDepleted; }

    private void HandleDepleted()
    {
        _node.OnDepleted -= HandleDepleted;

        foreach (Collider col in GetComponentsInChildren<Collider>())
            col.enabled = false;

        // Stop the billboard from overwriting the topple rotation each LateUpdate.
        Billboard billboard = GetComponentInChildren<Billboard>();
        if (billboard != null) billboard.enabled = false;

        StartCoroutine(FallRoutine());
    }

    private IEnumerator FallRoutine()
    {
        Vector3 startPos = _visualRoot.position;
        Quaternion startRot = _visualRoot.rotation;
        Vector3 axis = Random.value < 0.5f ? Vector3.forward : Vector3.back;

        Color baseColor = _spriteRenderer != null ? _spriteRenderer.color : Color.white;
        float total = Mathf.Max(_fallDuration, _fadeDuration);
        float t = 0f;

        while (t < total)
        {
            t += Time.deltaTime;
            float fall = Mathf.Clamp01(t / _fallDuration);
            float eased = fall * fall; // accelerate as it falls
            _visualRoot.rotation = startRot * Quaternion.AngleAxis(_toppleAngle * eased, axis);
            _visualRoot.position = startPos + Vector3.down * (_sink * eased);

            if (_spriteRenderer != null)
            {
                float alpha = baseColor.a * (1f - Mathf.Clamp01(t / _fadeDuration));
                _spriteRenderer.color = new Color(baseColor.r, baseColor.g, baseColor.b, alpha);
            }
            yield return null;
        }

        Destroy(gameObject);
    }
}

