/// <summary>
/// Tool category used by ResourceNode to select the correct attack animation
/// and (in future) to gate which tool is required for harvesting.
/// </summary>
public enum ItemType
{
    None    = 0,
    Pick    = 1,
    Axe     = 2,
    Hammer  = 3,
