    {
        Debug.Log($"[AudioManager] Play low-battery warning \u2014 {evt.Percent:P0}");
    }

    private void OnBatteryEmpty(BatteryEmpty evt)
    {
        Debug.Log("[AudioManager] Play battery-dead tone");
    }
}

