using UnityEditor;
using UnityEngine;

// ── Find config assets ──────────────────────────────────────────────────────
var woodConfig = AssetDatabase.LoadAssetAtPath<ResourceNodeConfig>("Assets/Flynn/Configs/Resources/Wood_Config.asset");
var techTrashConfig = AssetDatabase.LoadAssetAtPath<ResourceNodeConfig>("Assets/Flynn/Configs/Resources/TechTrash_Config.asset");

// ── Wood_Test: add ResourceNode, assign Wood_Config ─────────────────────────
var woodGo = GameObject.Find("Wood_Test");
if (woodGo != null)
{
    var resNode = woodGo.AddComponent<ResourceNode>();
    var serialized = new SerializedObject(resNode);
    var configProp = serialized.FindProperty("_config");
    if (configProp != null)
    {
        configProp.objectReferenceValue = woodConfig;
        serialized.ApplyModifiedProperties();
    }
    Debug.Log($"Wood_Test: ResourceNode added, config = {woodConfig.name}");
}
else Debug.LogError("Wood_Test not found!");

// ── TechTrash_Test: add ResourceNode, assign TechTrash_Config ───────────────
var trashGo = GameObject.Find("TechTrash_Test");
if (trashGo != null)
{
    var resNode = trashGo.AddComponent<ResourceNode>();
    var serialized = new SerializedObject(resNode);
    var configProp = serialized.FindProperty("_config");
    if (configProp != null)
    {
        configProp.objectReferenceValue = techTrashConfig;
        serialized.ApplyModifiedProperties();
    }
    Debug.Log($"TechTrash_Test: ResourceNode added, config = {techTrashConfig.name}");
}
else Debug.LogError("TechTrash_Test not found!");

// ── Artifact_Scan_Test: add ScanTarget ──────────────────────────────────────
var scanGo = GameObject.Find("Artifact_Scan_Test");
if (scanGo != null)
{
    scanGo.AddComponent<ScanTarget>();
    Debug.Log("Artifact_Scan_Test: ScanTarget added");
}
else Debug.LogError("Artifact_Scan_Test not found!");

Debug.Log("Test GameObject setup complete.");

